INSERT INTO news (title, body, snippet, image_key, published_at) VALUES ('Another huge entry at Thoresby gives Irish breeding a serious showcase', 'Another huge entry at Thoresby gives Irish breeding a serious showcase, with more than 50% of Top 10 places taken in the CCIs.
INSERT INTO news (title, body, snippet, image_key, published_at) VALUES ('Sire watch: OBOS Quality 004 leads the way at Thoresby and Oxstalls', 'OBOS Quality 004 tops the sire list this week, with seven of his progeny competing across Thoresby and Oxstalls, from Novice through to CCI 3*. Sligo Candy Boy isn''t far behind with six. It''s exactly the kind of pattern breeders ask about — and once results are entered weekly, the site can surface it automatically instead of someone totting it up by hand.', 'Seven horses by OBOS Quality 004 were out across Thoresby and Oxstalls this week — more progeny competing than any other sire on the list.', NULL, '2026-04-06 11:00:00');
INSERT INTO news (title, body, snippet, image_key, published_at) VALUES ('Twenty-eight of this week''s horses are competing under a different name', 'It''s one of the first things people notice when they start using this site properly: search a horse''s old name and it still finds it. This week alone, 28 of the 127 entries carry a former name in the records — including Cooley Park Muze, winner of the Grantham Cup at Thoresby, who spent his early career as TJM Reuben. That matters most to breeders, who often lose track of a horse the moment it''s sold on and renamed. Type either name here and you''ll find the same horse.', 'From Cooley Park Muze — this week''s Grantham Cup winner, formerly TJM Reuben — to Global Quest, once known as Metro Super Star, more than one in five of this week''s entries carry a former name. Search matches both.', NULL, '2026-04-06 10:00:00');
INSERT INTO news (title, body, snippet, image_key, published_at) VALUES ('Corrections and additions from last week''s list', 'Two horses were missing from last week''s Ballindenisk entries and have now been added to the archive. A breeder credit has also been corrected.
INSERT INTO news (title, body, snippet, image_key, published_at) VALUES ('Oxstalls and Bicton entries make for a busy fortnight ahead', 'A heavy entry at both Oxstalls and Bicton over the coming fortnight, with a strong Irish-bred presence through the Novice and Intermediate sections.
INSERT INTO news (title, body, snippet, image_key, published_at) VALUES ('A note on former names, and why they''re kept in the record', 'Horses get renamed when they''re sold on, sometimes more than once. For a breeder trying to follow a horse they bred and sold as a three-year-old, a new name is the point at which the trail goes cold.
INSERT INTO comments (scope, name, body, status, created_at) VALUES ('results', 'Sarah', 'Lovely to see a horse I bred placed again this week. Thank you for keeping the results going.', 'approved', '2026-04-06 10:00:00');
INSERT INTO comments (scope, name, body, status, created_at) VALUES ('results', 'Tom', 'Great to have every result in one place, free to read.', 'approved', '2026-04-07 10:00:00');
